def parse_version(s):
    if not s:
        raise ValueError('empty string')
    parts = s.split('.')
    result = []
    for part in parts:
        if part == '':
            raise ValueError('empty component')
        if not part.isdigit():
            raise ValueError('non-numeric component')
        result.append(int(part))  # Append the current part, not the entire string
    return tuple(result)  # Return a tuple instead of a list
```
